"use client";
import{useRef,useState}from'react';
import{RaceViewer,VIEWER_VERSION,validateFeed,type ViewerFeed,type RaceViewerHandle,type CameraTarget}from'@pelotonia/race-viewer';
const tick=()=>new Promise<void>(resolve=>requestAnimationFrame(()=>requestAnimationFrame(()=>resolve())));
const target:CameraTarget={type:'group',id:'selection-test'},clock={position:0,serverEpochMs:0,duration:240,rate:1,paused:true};
/** Flat, source-authored selection fixture. Does not move a hidden rider for product selection. */
export default function SelectionAcceptance(){
 const[feed,setFeed]=useState<ViewerFeed>(),[status,setStatus]=useState('Ready'),[busy,setBusy]=useState(false),a=useRef<RaceViewerHandle>(null),b=useRef<RaceViewerHandle>(null),host=useRef<HTMLDivElement>(null),picked=useRef<Record<string,CameraTarget>>({});
 async function settle(){for(let i=0;i<180;i++){await tick();if(a.current?.getDiagnostics()?.cameraSettled&&b.current?.getDiagnostics()?.cameraSettled)return;}throw Error('Camera did not settle');}
 function clickRider(index:number,viewer:RaceViewerHandle){const canvas=host.current!.querySelectorAll('canvas')[index],rect=canvas.getBoundingClientRect(),camera=viewer.getCameraState()!;if(!camera.position||!camera.focus||!camera.aspect||!camera.verticalFovDegrees)throw Error('Missing projection');const subtract=(x:number[],y:number[])=>x.map((v,i)=>v-y[i]),normal=(v:number[])=>{const n=Math.hypot(...v);return v.map(x=>x/n)},cross=(u:number[],v:number[])=>[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]],dot=(u:number[],v:number[])=>u.reduce((s,x,i)=>s+x*v[i],0),forward=normal(subtract(camera.focus,camera.position)),right=normal(cross(forward,[0,1,0])),up=cross(right,forward),point=subtract([.04,1.18,0],camera.position),depth=dot(point,forward),tan=Math.tan(camera.verticalFovDegrees*Math.PI/360),x=dot(point,right)/(depth*tan*camera.aspect),y=dot(point,up)/(depth*tan);if(Math.abs(x)>1||Math.abs(y)>1)throw Error('Source rider not in viewport');canvas.dispatchEvent(new MouseEvent('click',{bubbles:true,clientX:rect.left+(x+1)*rect.width/2,clientY:rect.top+(1-y)*rect.height/2}));}
 async function run(){setBusy(true);try{setStatus('Loading source-authored selection fixture');const source=await(await fetch('/demo-feed-v1.json')).json() as ViewerFeed;source.raceId='selection-fixture';source.route={width:8,points:[[-100,0,0],[100,0,0]],interpolation:'polyline'};delete source.terrain;delete source.finish;delete source.results;source.landmarks=[];source.assets=[];source.spectators=[];source.waterBodies=[];source.orders=[];source.actions=[];source.events=[];source.frames=source.frames.map(frame=>({time:frame.time,positions:frame.positions,gaps:{}}));for(const frame of source.frames){frame.positions.forEach((p,i)=>{p.distance=i===0?100:80-i*.1;p.lateral=i===0?0:(i%5-2)*.5;p.groupId='selection-test';p.cadence=80;});}validateFeed(source);picked.current={};setFeed(source);for(let i=0;i<60&&(!a.current||!b.current);i++)await tick();if(!a.current||!b.current)throw Error('Missing spectators');await Promise.all([a.current.whenAssetsReady(),b.current.whenAssetsReady()]);await settle();const before=JSON.stringify(source),canvases=[...host.current!.querySelectorAll('canvas')];clickRider(0,a.current);await tick();if(picked.current.a?.id!=='r1'||a.current.getSnapshot().target?.id!=='selection-test')throw Error('Controlled camera changed or click missed');clickRider(1,b.current);await settle();if(picked.current.b?.id!=='r1'||b.current.getSnapshot().target?.id!=='r1')throw Error('Uncontrolled click: picked='+JSON.stringify(picked.current.b)+' target='+JSON.stringify(b.current.getSnapshot().target));if(a.current.getSnapshot().time!==0||b.current.getSnapshot().time!==0||JSON.stringify(source)!==before||canvases.some((c,i)=>host.current!.querySelectorAll('canvas')[i]!==c))throw Error('Selection changed time, source or canvas');setStatus('PASS — actual canvas picking; controlled host camera retained; uncontrolled rider followed; source data and shared clock unchanged. '+VIEWER_VERSION);}catch(e){setStatus('FAIL — '+(e instanceof Error?e.message:String(e)))}finally{setBusy(false)}}
 return <main style={{fontFamily:'system-ui',padding:16,background:'#edf0e5',color:'#294232'}}><h1>Selection ownership · {VIEWER_VERSION}</h1><p>Synthetic flat route. Left: controlled group. Right: local rider selection.</p><button disabled={busy} onClick={run}>Run canvas selection acceptance</button><p role="status">{status}</p><div ref={host} style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:12}}>{feed&&<><RaceViewer ref={a} feed={feed} clock={clock} target={target} onSelect={t=>{picked.current.a=t}} style={{height:480}}/><RaceViewer ref={b} feed={feed} clock={clock} onSelect={t=>{picked.current.b=t}} style={{height:480}}/></>}</div></main>;
}
